function reindent(text, opts){
  opts=opts||{}; var delta=opts.delta!=null?opts.delta:1; var unit=opts.unit||'  ';
  var lines=String(text||'').split(/\r?\n/); var out=[];
  for(var i=0;i<lines.length;i++){
    var L=lines[i];
    if(delta>=0){ var add=''; for(var k=0;k<delta;k++) add+=unit; out.push(add+L); }
    else { var lim=-delta*unit.length, j=0;
      while(j<L.length && j<lim && (L.charAt(j)===' ' || L.charAt(j)==='\t')) j++;
      out.push(L.slice(j));
    }
  }
  return out.join('\n');
}

var EXPORTS={reindent:reindent};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.IndentForgePure = EXPORTS; }
